+    private static RuntimeState runtimeFor(ServerLevel level) {
+        synchronized (RUNTIMES) {
+            return RUNTIMES.computeIfAbsent(
+                    level,
+                    loadedLevel -> {
+                        VolcanoSavedData data = VolcanoSavedData.get(loadedLevel);
+                        return new RuntimeState(
